"""Operator report for a detected anomaly, generated by OpenAI GPT"""

from __future__ import annotations

import os
import textwrap
from dataclasses import dataclass
from pathlib import Path
from typing import Optional

# Load .env before anything else
from dotenv import load_dotenv
load_dotenv(Path(__file__).resolve().parents[1] / ".env")

import openai

# Agent display names (Ukrainian, for LLM reports only)
_AGENT_UA: dict[str, str] = {
    "SetpointAgent": "Агент уставок",
    "ControlOutputAgent": "Керуючі виходи",
    "LSTMAutoencoderAgent": "LSTM-автоенкодер",
    "ProtectionAgent": "Захист P2",
    "ConsistencyAgent": "Узгодженість P1/P2/P4",
    "P1P4SentinelAgent": "Sentinel P1/P4",
}

from src.anomaly_event import AnomalyEvent


@dataclass
class LLMReport:
    """Result of one LLM call"""
    event: AnomalyEvent
    text: str           # full human-readable report
    severity: str       # "HIGH" | "MEDIUM" | "LOW"
    model: str
    prompt_tokens: int
    completion_tokens: int


_SYSTEM_PROMPT = textwrap.dedent("""\
    Ти — аналітик з експлуатації та кіберзахисту АСУ ТП (ICS/SCADA) на тренажері HAI.
    Формуєш операторський звіт за даними мультиагентного IDS (не сирі логи, а інтерпретація).

    Стиль:
    - Українська, стисло, без канцеляриту та без «води».
    - Не використовуй розмиті формулювання: «можливо», «ймовірно», «потенційні відхилення»,
      «можливі проблеми» — формулюй впевнено, спираючись на факти з вхідних даних.
    - Тон: інженер-оператор і аналітик безпеки; припущення позначай як «гіпотеза», лише якщо
      даних недостатньо.
    - Пояснюй фізичний зміст (контур P2, уставки, керуючі впливи, узгодженість P1/P4).

    Структура (обов’язково, без Markdown-зірочок **):
    [SEVERITY: HIGH|MEDIUM|LOW]

    Опис події:
    2–3 речення — що зафіксовано, коли, тривалість, зона установки (контур P2).

    Аналіз агентів:
    які агенти спрацювали; узгодженість сигналів; роль оркестратора (причинно-часовий
    ланцюг: зміна уставки → стійка реакція LSTM; міжконтурний залишок; групове
    підтвердження); найвища нормована оцінка і її значення.

    Оцінка ризику:
    чому обрано рівень HIGH/MEDIUM/LOW (вплив на процес, потреба реакції). Про хибне
    спрацювання пиши: «ймовірність хибного спрацювання є низькою, оскільки аномалію
    підтверджено кількома незалежними ознаками» — не «хибне спрацювання малоймовірне».

    Рекомендації оператору:
    3–5 нумерованих кроків (журнал SCADA, уставки та швидкість P2, суміжні P1/P4,
    ескалація) — конкретні, виконувані.

    Термінологія:
    - «оркестратор» — алгоритм злиття сигналів; «оператор» — лише людина на зміні.
    - Не пиши «оператор використовує ланцюг» — пиши «оркестратор використовує
      причинно-часовий ланцюг».
""")


def _build_user_prompt(event: AnomalyEvent) -> str:
    """Turn an event into the user prompt text"""
    active_ua = [_AGENT_UA.get(a, a) for a in event.active_agents]
    scores_str = "\n".join(
        f"  - {_AGENT_UA.get(k, k)}: {v:.3f}"
        for k, v in sorted(event.agent_scores.items(), key=lambda x: -x[1])
    ) or "  (недоступно)"

    fusion_parts = []
    if event.chain_flag:
        fusion_parts.append("причинний ланцюг (уставки → LSTM)")
    if event.residual_flag:
        fusion_parts.append("крос-залишок між контурами")
    if event.vote_flag:
        fusion_parts.append("консенсус голосування (≥2 групи агентів)")
    fusion_str = ", ".join(fusion_parts) if fusion_parts else "пряме спрацювання агента"

    extra_str = ""
    if event.extra:
        extra_str = "\nДодатковий контекст:\n" + "\n".join(
            f"  {k}: {v}" for k, v in event.extra.items()
        )

    return textwrap.dedent(f"""\
        Виявлено аномальний інтервал:
        - Початок: {event.timestamp_start}  (рядок {event.start_row})
        - Кінець:  {event.timestamp_end}    (рядок {event.end_row})
        - Тривалість: {event.duration_sec} секунд

        Активні агенти ({len(event.active_agents)}):
        {chr(10).join("  - " + a for a in active_ua) or "  (немає)"}

        Нормовані аномальні оцінки:
        {scores_str}

        Механізм злиття (orchestrator): {fusion_str}
        {extra_str}
        Сформуй операторський звіт у вказаній структурі (академічно-діловий стиль).
    """)


class LLMJudge:
    """Generates incident reports with the OpenAI chat API (key from .env)"""

    def __init__(
        self,
        model: str = "gpt-4o-mini",
        api_key: Optional[str] = None,
    ) -> None:
        key = api_key or os.getenv("OPENAI_API_KEY")
        if not key:
            raise EnvironmentError(
                "OPENAI_API_KEY not set. Add it to .env or pass api_key= explicitly."
            )
        self._client = openai.OpenAI(api_key=key)
        self.model = model

    def explain(self, event: AnomalyEvent) -> LLMReport:
        """Generate an incident report for one anomaly event"""
        user_prompt = _build_user_prompt(event)

        try:
            response = self._client.chat.completions.create(
                model=self.model,
                messages=[
                    {"role": "system", "content": _SYSTEM_PROMPT},
                    {"role": "user",   "content": user_prompt},
                ],
                temperature=0.2,
                max_tokens=750,
            )
        except openai.RateLimitError as e:
            raise RuntimeError(
                "OpenAI quota exceeded. Add billing credits at "
                "https://platform.openai.com/settings/billing\n"
                f"Original error: {e}"
            ) from e

        text = response.choices[0].message.content.strip()

        # Extract severity tag from the report
        severity = "MEDIUM"
        for line in text.splitlines():
            if "[SEVERITY:" in line.upper():
                if "HIGH"   in line.upper(): severity = "HIGH"
                elif "LOW"  in line.upper(): severity = "LOW"
                else: severity = "MEDIUM"
                break

        return LLMReport(
            event=event,
            text=text,
            severity=severity,
            model=self.model,
            prompt_tokens=response.usage.prompt_tokens,
            completion_tokens=response.usage.completion_tokens,
        )
